script:
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
$configDir = "$env:USERPROFILE\.config\opencode"

# Set GitHub token as user env var (for GitHub MCP)
[Environment]::SetEnvironmentVariable("GITHUB_TOKEN", "NOT_FOUND", "User")
$env:GITHUB_TOKEN = "NOT_FOUND"
"GITHUB_TOKEN set"

# Write opencode.json with model + MCPs + plugins
$config = @{
  model = "opencode/space-bunny-free"
  plugin = @(
    "opencode-vibeguard",
    "opencode-shell-strategy",
    "@tarquinen/opencode-dcp",
    "@zenobius/opencode-skillful"
  )
  mcp = @{
    context7 = @{
      type = "remote"
      url = "https://mcp.context7.com/mcp"
      enabled = $true
    }
    playwright = @{
      type = "local"
      command = @("npx", "-y", "@playwright/mcp")
      enabled = $true
    }
    github = @{
      type = "local"
      command = @("npx", "-y", "@modelcontextprotocol/server-github")
      environment = @{ GITHUB_PERSONAL_ACCESS_TOKEN = "{env:GITHUB_TOKEN}" }
      enabled = $true
    }
    memory = @{
      type = "local"
      command = @("npx", "-y", "@modelcontextprotocol/server-memory")
      enabled = $true
    }
  }
}
$config | ConvertTo-Json -Depth 10 | Out-File -FilePath "$configDir\opencode.json" -Encoding utf8
"opencode.json written"
Get-Content "$configDir\opencode.json" | Select-Object -First 5
